/**
 * @file scenes.c
 * @brief 场景注册表。
 */

#include <stdio.h>
#include <string.h>

#include "sim.h"

#ifdef SIM_WITH_UI
/**
 * @brief `ui` 场景：把屏幕交给 vendor 的真实自行车 UI。
 *
 * 这里**不建任何控件** —— `sim_ui_start()` 会照板端 `bicycle_c_main.c` 的
 * 顺序初始化页面管理器、压开机 splash，并用定时器接管后续每拍工作。
 * 屏幕尺寸用启动参数（默认 240x320，与设备一致）。
 */
static void scene_ui_create(lv_obj_t *scr, const sim_cfg_t *cfg)
{
    (void)scr;
    /* 巡页（--ui-tour）只影响 `ui` 场景；未配置时 sim_ui_start 行为不变。 */
    sim_ui_tour_configure(cfg->ui_tour, cfg->tour_frames);
    sim_ui_start();
}
#endif

static const sim_scene_t s_scenes[] = {
    { "demo",      "控件总览：按钮/滑杆/开关/图表/中文字体", scene_demo_create },
#ifdef SIM_WITH_UI
    /* `vmap` = 真 vmap 组件：读 mkfs/fat/map 的 z14 网格包，鼠标拖动/滚轮缩放，
     * HUD 显示 lon/lat/scale/viewport/中心图标（见 ui_port/scene_vmap_live.c）。 */
    { "vmap",      "真 vmap 组件：z14 网格包 + 拖动/缩放 + HUD", scene_vmap_live_create },
#endif
    { "vmap-mock", "vmap 底图 mock：RGB565 canvas + 直接光栅化 + 中文标注", scene_vmap_create },
#ifdef SIM_WITH_UI
    { "ui",   "真实自行车 UI（vendor ui/bicycle）：开机 splash → 主界面", scene_ui_create },
#endif
};

#define SCENE_COUNT (sizeof(s_scenes) / sizeof(s_scenes[0]))

const sim_scene_t *sim_scene_find(const char *name)
{
    if (!name) {
        return NULL;
    }
    for (size_t i = 0; i < SCENE_COUNT; i++) {
        if (strcmp(s_scenes[i].name, name) == 0) {
            return &s_scenes[i];
        }
    }
    return NULL;
}

void sim_scene_list(void)
{
    puts("可用场景:");
    for (size_t i = 0; i < SCENE_COUNT; i++) {
        printf("  %-8s %s\n", s_scenes[i].name, s_scenes[i].desc);
    }
}

/**
 * @file sim.h
 * @brief LVGL 模拟器公共接口（显示 / 输入 / 截图 / 场景）。
 */

#ifndef SIM_H
#define SIM_H

#include <stdbool.h>
#include <stdint.h>

#include "lvgl.h"

#ifdef __cplusplus
extern "C" {
#endif

typedef struct {
    int width;          /**< 设备像素宽，默认 240 */
    int height;         /**< 设备像素高，默认 320（设备原生竖屏） */
    int scale;          /**< 窗口放大倍数，默认 2 */
    const char *title;  /**< 窗口标题 */
    bool headless;      /**< 不建窗口，跑固定帧数后截图 */
    const char *shot;   /**< headless 下的 PNG 输出路径 */
    int frames;         /**< headless 跑多少帧，默认 30 */
    const char *ui_tour; /**< `ui` 场景巡页截图目录（NULL = 关闭，默认） */
    int tour_frames;    /**< 巡页每页等待帧数，默认 90 */

    /* ── `vmap` 场景（真 vmap 组件）的启动参数 ─────────────────────── */
    int vmap_w;           /**< viewport 宽，0 = 用屏幕宽 */
    int vmap_h;           /**< viewport 高，0 = 用屏幕高 */
    double vmap_lon;      /**< 中心经度；NaN = 用组件默认（板端开机中心） */
    double vmap_lat;      /**< 中心纬度 */
    double vmap_scale;    /**< 连续缩放；<=0 = 组件默认（1.69） */
    int vmap_zoom;        /**< 瓦片层级，0 = 默认 z14 */
    int vmap_icon;        /**< sim_vmap_icon_t */
    int vmap_pan_x;       /**< 首帧后一次性平移量（像素，脚本化拖动取证） */
    int vmap_pan_y;
    bool vmap_pan_set;
    int vmap_rw;          /**< 首帧后运行时改 viewport 宽（0 = 不改） */
    int vmap_rh;          /**< 首帧后运行时改 viewport 高 */
    bool vmap_hud;        /**< 显示 HUD（默认 true） */
    bool vmap_heading;    /**< 航向朝上（R 缓冲旋转显示） */
    double vmap_course;   /**< 航向角（度，正北 0 顺时针）；配合 heading */

    /* 锚点缩放 `vmap_view_zoom_at()`：最多两处，按给定顺序在首帧后执行。 */
    int vmap_zoom_at_n;
    int vmap_za_x[2];
    int vmap_za_y[2];
    double vmap_za_f[2];

    /* 运行时换中心图标（每拍换一次，只调 `set_center_icon()`）：
     * 验证"换图后朝向/旋转逻辑仍在"，不借助 update_arrow。 */
    int vmap_swap_n;
    int vmap_swap_icon[3];

    /* 跟车：喂 N 个向东移动的 GNSS 点（板端热路径 vmap_view_set_center）。 */
    int vmap_follow_n;
    double vmap_follow_m;      /**< 每步东移米数 */

    /* 拖动之后调一次 `center_on()` 回中（验证"可回中 + 不弹回"）。 */
    bool vmap_recenter;

    /* 连续拖动 `vmap_view_pan_px()`：N 步 × (dx,dy)，每步等泵空闲。 */
    int vmap_drag_n;
    int vmap_drag_x;
    int vmap_drag_y;
} sim_cfg_t;

/** @brief `--vmap-icon` 的取值。 */
typedef enum {
    SIM_VMAP_ICON_DEV = 0,  /**< 板端导航箭头（NaviArrow light，默认） */
    SIM_VMAP_ICON_ALT,      /**< 另一枚图标（模拟器运行时画的准星），验证"可换图" */
    SIM_VMAP_ICON_NONE,     /**< 不画中心图标 */
} sim_vmap_icon_t;

/* ── 显示 ──────────────────────────────────────────────────────── */

/** 建窗口（或 headless 下什么都不建）。返回 false 表示失败。 */
bool sim_display_init(const sim_cfg_t *cfg);

/** 把 LVGL 刷出来的一块 RGB565 送到窗口/影子帧缓冲。 */
void sim_display_present(const lv_area_t *area, const uint16_t *px, int stride_px);

/** 处理一次 X 事件；返回 false 表示窗口被关掉。 */
bool sim_display_pump(void);

void sim_display_shutdown(void);

/** headless 下的整帧影子缓冲（RGB565，w*h）。 */
const uint16_t *sim_display_shadow(int *w, int *h);

/** 显示初始化后调用：把 flush_cb / indev 挂到 LVGL 上。 */
void sim_lvgl_bind(void);

/** 键盘焦点组（场景里把可聚焦控件加进来）。 */
lv_group_t *sim_input_group(void);

/** 中文字体（FreeType + 系统 TTF），按字号缓存；失败时退回内置子集。 */
lv_font_t *sim_font_cjk(int px);

/** 同上，可指定斜体（水名习惯用斜体）。 */
lv_font_t *sim_font_cjk_style(int px, bool italic);

/* ── 截图 ──────────────────────────────────────────────────────── */

/** RGB565 帧缓冲 → PNG。 */
bool sim_png_write(const char *path, const uint16_t *fb, int w, int h);

/* ── 场景 ──────────────────────────────────────────────────────── */

typedef void (*sim_scene_fn_t)(lv_obj_t *scr, const sim_cfg_t *cfg);

typedef struct {
    const char *name;
    const char *desc;
    sim_scene_fn_t create;
} sim_scene_t;

const sim_scene_t *sim_scene_find(const char *name);
void sim_scene_list(void);

void scene_demo_create(lv_obj_t *scr, const sim_cfg_t *cfg);
void scene_vmap_create(lv_obj_t *scr, const sim_cfg_t *cfg);

/**
 * @brief 真 vmap 组件场景（读 mkfs/fat/map 的 z14 网格包）。
 *
 * 与 `scene_vmap_create`（mock 底图）不同：这里建的是 vendor 里真正的
 * `vmap_view_t`，鼠标拖动 = 平移、滚轮 = 连续缩放、HUD 显示
 * lon/lat/scale/viewport/中心图标，启动参数见 sim_cfg_t 的 vmap_* 字段。
 * 只在 SIM_WITH_UI（真实 UI 库）下可用。
 */
void scene_vmap_live_create(lv_obj_t *scr, const sim_cfg_t *cfg);

/* ── 窗口/输入附加通道（`vmap` 场景用；其它场景不消费） ──────────── */

/** @brief 取走累计的鼠标滚轮格数（上滚 +1 / 下滚 -1）。 */
int sim_display_take_wheel(void);

/** @brief 取走一个"原始按键"（'1'..'9' / '+' / '-' / 'r' / 'f' / 'i'），无则 0。 */
int sim_display_take_raw_key(void);

/**
 * @brief 启动 vendor/my_vendor 里真实的自行车 UI（`ui` 场景）。
 *
 * 只有 `SIM_WITH_UI=ON`（默认）编进来时才有定义；它自己接管屏幕，场景函数
 * 调完立刻返回。实现见 ui_port/ui_boot.c。
 */
void sim_ui_start(void);

/* ── `ui` 场景巡页（模拟器专用；只在 SIM_WITH_UI 下有定义） ────── */

/** 记录巡页参数；必须在 sim_ui_start() 之前调用。dir=NULL 关闭巡页。 */
void sim_ui_tour_configure(const char *dir, int frames);
/** 开机序列结束后启动巡页（ui_boot.c 末尾调用；未配置时为空操作）。 */
void sim_ui_tour_start(void);
/** 巡页结束（或失败）后返回 true；headless 主循环据此退出。 */
bool sim_ui_tour_done(void);
/** 是否配置了巡页（未配置时主循环行为完全不变）。 */
bool sim_ui_tour_enabled(void);

/* ── WP-FADE/R1 临时探针（环境变量 SIM_FADE_PROBE_DIR；取证后删除） ────── */
void sim_ui_fade_probe_start(void);
bool sim_ui_fade_probe_done(void);

#ifdef __cplusplus
}
#endif

#endif /* SIM_H */
