/**
 * @file sim_font.c
 * @brief 中文字体：桌面用 FreeType 挂系统 TTF，按字号/字形缓存。
 *
 * 板子上用的是定制点阵字库，模拟器没有；这里用 SourceHanSansCN
 * （同族、同字形风格）来近似，主要为了看路名/地名的字号与排版。
 * 字体路径可用环境变量 SIM_CJK_FONT 覆盖。
 */

#include <stdio.h>
#include <stdlib.h>

#include "sim.h"

#define SIM_FONT_CACHE 12

static struct {
    int px;
    bool italic;
    lv_font_t *font;
} s_cache[SIM_FONT_CACHE];
static int s_cache_n;

static const char *cjk_font_path(void)
{
    const char *env = getenv("SIM_CJK_FONT");

    if (env && env[0]) {
        return env;
    }
    /* 用**码表固件里那份** TTF（MiSans-Medium 子集），字形与板端一致。
     * 设备路径是 /mnt/fat/fonts/MiSans-Medium.subset.ttf。 */
    return "/home/jinsc/SDK/vela/openvela/vendor/my_vendor/boards/sf32lb52/my_vendor/mkfs/fat/fonts/MiSans-Medium.subset.ttf";
}

lv_font_t *sim_font_cjk_style(int px, bool italic)
{
    if (px < 6) {
        px = 6;
    }
    for (int i = 0; i < s_cache_n; i++) {
        if (s_cache[i].px == px && s_cache[i].italic == italic) {
            return s_cache[i].font;
        }
    }

    lv_font_t *font = lv_freetype_font_create(cjk_font_path(),
                                              LV_FREETYPE_FONT_RENDER_MODE_BITMAP,
                                              (uint32_t)px,
                                              italic ? LV_FREETYPE_FONT_STYLE_ITALIC
                                                     : LV_FREETYPE_FONT_STYLE_NORMAL);
    if (!font) {
        fprintf(stderr, "sim: cannot load CJK font %s, using built-in subset\n",
                cjk_font_path());
        font = (lv_font_t *)&lv_font_source_han_sans_sc_16_cjk;
    }

    if (s_cache_n < SIM_FONT_CACHE) {
        s_cache[s_cache_n].px = px;
        s_cache[s_cache_n].italic = italic;
        s_cache[s_cache_n].font = font;
        s_cache_n++;
    }
    return font;
}

lv_font_t *sim_font_cjk(int px)
{
    return sim_font_cjk_style(px, false);
}
