/**
 * @file sim_png.c
 * @brief RGB565 帧缓冲 → PNG（headless 截图用）。
 */

#include <png.h>
#include <setjmp.h>
#include <stdio.h>
#include <stdlib.h>

#include "sim.h"

bool sim_png_write(const char *path, const uint16_t *fb, int w, int h)
{
    if (!path || !fb || w <= 0 || h <= 0) {
        return false;
    }

    FILE *fp = fopen(path, "wb");
    if (!fp) {
        perror(path);
        return false;
    }

    png_structp png = png_create_write_struct(PNG_LIBPNG_VER_STRING, NULL, NULL, NULL);
    if (!png) {
        fclose(fp);
        return false;
    }
    png_infop info = png_create_info_struct(png);
    if (!info) {
        png_destroy_write_struct(&png, NULL);
        fclose(fp);
        return false;
    }

    uint8_t *row = NULL;
    if (setjmp(png_jmpbuf(png))) {
        free(row);
        png_destroy_write_struct(&png, &info);
        fclose(fp);
        return false;
    }

    png_init_io(png, fp);
    png_set_IHDR(png, info, (png_uint_32)w, (png_uint_32)h, 8,
                 PNG_COLOR_TYPE_RGB, PNG_INTERLACE_NONE,
                 PNG_COMPRESSION_TYPE_DEFAULT, PNG_FILTER_TYPE_DEFAULT);
    png_write_info(png, info);

    row = malloc((size_t)w * 3u);
    if (!row) {
        png_destroy_write_struct(&png, &info);
        fclose(fp);
        return false;
    }

    for (int y = 0; y < h; y++) {
        const uint16_t *src = fb + (size_t)y * (size_t)w;
        for (int x = 0; x < w; x++) {
            const uint16_t c = src[x];
            const uint32_t r5 = (uint32_t)((c >> 11) & 0x1Fu);
            const uint32_t g6 = (uint32_t)((c >> 5) & 0x3Fu);
            const uint32_t b5 = (uint32_t)(c & 0x1Fu);

            row[x * 3 + 0] = (uint8_t)((r5 << 3) | (r5 >> 2));
            row[x * 3 + 1] = (uint8_t)((g6 << 2) | (g6 >> 4));
            row[x * 3 + 2] = (uint8_t)((b5 << 3) | (b5 >> 2));
        }
        png_write_row(png, row);
    }

    png_write_end(png, NULL);
    free(row);
    png_destroy_write_struct(&png, &info);
    fclose(fp);
    return true;
}

/**
 * @file scene_demo.c
 * @brief 通用控件场景：用来确认模拟器本身（显示/输入/中文字体）是好的。
 */

#include <math.h>

#include "sim.h"

static void slider_cb(lv_event_t *e)
{
    lv_obj_t *label = lv_event_get_user_data(e);
    lv_obj_t *slider = lv_event_get_target(e);
    char buf[32];

    lv_snprintf(buf, sizeof(buf), "%d%%", (int)lv_slider_get_value(slider));
    lv_label_set_text(label, buf);
}

void scene_demo_create(lv_obj_t *scr, const sim_cfg_t *cfg)
{
    lv_obj_set_style_bg_color(scr, lv_color_hex(0x0F172A), 0);
    lv_obj_set_style_bg_opa(scr, LV_OPA_COVER, 0);
    lv_obj_remove_flag(scr, LV_OBJ_FLAG_SCROLLABLE);

    lv_obj_t *title = lv_label_create(scr);
    lv_label_set_text(title, "LVGL 模拟器");
    lv_obj_set_style_text_font(title, sim_font_cjk(20), 0);
    lv_obj_set_style_text_color(title, lv_color_hex(0xF8FAFC), 0);
    lv_obj_align(title, LV_ALIGN_TOP_MID, 0, 14);

    lv_obj_t *sub = lv_label_create(scr);
    lv_label_set_text_fmt(sub, "v%d.%d.%d   %dx%d   RGB565",
                          LVGL_VERSION_MAJOR, LVGL_VERSION_MINOR,
                          LVGL_VERSION_PATCH, cfg->width, cfg->height);
    lv_obj_set_style_text_font(sub, &lv_font_montserrat_12, 0);
    lv_obj_set_style_text_color(sub, lv_color_hex(0x94A3B8), 0);
    lv_obj_align(sub, LV_ALIGN_TOP_MID, 0, 42);

    /* 按钮行 */
    static const char *const names[] = { "开始", "暂停", "重置" };
    lv_obj_t *row = lv_obj_create(scr);
    lv_obj_remove_style_all(row);
    lv_obj_set_size(row, 200, 40);
    lv_obj_align(row, LV_ALIGN_TOP_MID, 0, 70);
    lv_obj_set_flex_flow(row, LV_FLEX_FLOW_ROW);
    lv_obj_set_flex_align(row, LV_FLEX_ALIGN_SPACE_EVENLY,
                          LV_FLEX_ALIGN_CENTER, LV_FLEX_ALIGN_CENTER);

    for (int i = 0; i < 3; i++) {
        lv_obj_t *btn = lv_button_create(row);
        lv_obj_set_size(btn, 60, 34);
        lv_obj_set_style_radius(btn, 8, 0);
        lv_obj_set_style_bg_color(btn, lv_color_hex(i == 0 ? 0xFF931E : 0x334155), 0);

        lv_obj_t *lbl = lv_label_create(btn);
        lv_label_set_text(lbl, names[i]);
        lv_obj_set_style_text_font(lbl, sim_font_cjk(14), 0);
        lv_obj_set_style_text_color(lbl, lv_color_hex(0xFFFFFF), 0);
        lv_obj_center(lbl);

        lv_group_add_obj(sim_input_group(), btn);
    }

    /* 滑杆 + 读数 */
    lv_obj_t *slider = lv_slider_create(scr);
    lv_obj_set_width(slider, 180);
    lv_obj_align(slider, LV_ALIGN_TOP_MID, 0, 132);
    lv_slider_set_range(slider, 0, 100);
    lv_slider_set_value(slider, 62, LV_ANIM_OFF);
    lv_obj_set_style_bg_color(slider, lv_color_hex(0xFF931E), LV_PART_INDICATOR);

    lv_obj_t *val = lv_label_create(scr);
    lv_label_set_text(val, "62%");
    lv_obj_set_style_text_font(val, &lv_font_montserrat_14, 0);
    lv_obj_set_style_text_color(val, lv_color_hex(0xE2E8F0), 0);
    lv_obj_align(val, LV_ALIGN_TOP_MID, 0, 156);
    lv_obj_add_event_cb(slider, slider_cb, LV_EVENT_VALUE_CHANGED, val);

    /* 图表：模拟速度曲线 */
    lv_obj_t *chart = lv_chart_create(scr);
    lv_obj_set_size(chart, 200, 110);
    lv_obj_align(chart, LV_ALIGN_TOP_MID, 0, 190);
    lv_obj_set_style_bg_color(chart, lv_color_hex(0x1E293B), 0);
    lv_obj_set_style_border_color(chart, lv_color_hex(0x334155), 0);
    lv_obj_set_style_radius(chart, 10, 0);
    lv_chart_set_type(chart, LV_CHART_TYPE_LINE);
    lv_chart_set_point_count(chart, 40);
    lv_chart_set_range(chart, LV_CHART_AXIS_PRIMARY_Y, 0, 60);

    lv_chart_series_t *ser = lv_chart_add_series(chart, lv_color_hex(0xFF931E),
                                                 LV_CHART_AXIS_PRIMARY_Y);
    for (int i = 0; i < 40; i++) {
        int v = 20 + (int)(18.0 * (1.0 + sinf((float)i * 0.35f)));
        lv_chart_set_next_value(chart, ser, v);
    }

    lv_obj_t *foot = lv_label_create(scr);
    lv_label_set_text(foot, "拖动滑杆 / 点击按钮 / 方向键切换焦点");
    lv_obj_set_style_text_font(foot, sim_font_cjk(12), 0);
    lv_obj_set_style_text_color(foot, lv_color_hex(0x64748B), 0);
    lv_obj_align(foot, LV_ALIGN_BOTTOM_MID, 0, -12);
}
