/**
 * @file main.c
 * @brief lvgl_sim 入口：参数解析 → LVGL 初始化 → 场景 → 主循环。
 *
 *   ./lvgl_sim                       # 默认 demo 场景，240x320 @2x 窗口
 *   ./lvgl_sim --scene vmap          # vmap 底图 mock
 *   ./lvgl_sim --scale 3             # 放大到 3 倍
 *   ./lvgl_sim --headless --frames 40 --shot out.png
 */

#include <getopt.h>
#include <math.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>

#include "sim.h"

uint32_t sim_tick_ms(void);

static uint32_t s_vtick;

static uint32_t vtick_get(void)
{
    return s_vtick;
}

static const char *const kUsageLines[] = {
    "用法: lvgl_sim [选项]",
    "  -s, --scene NAME    场景（demo | vmap | vmap-mock | ui），默认 demo",
    "  -S, --size WxH      设备分辨率，默认 240x320（设备原生竖屏）",
    "  -k, --scale N       窗口放大倍数，默认 2",
    "  -H, --headless      不建窗口，跑固定帧数",
    "  -f, --frames N      headless 帧数，默认 30",
    "  -o, --shot PATH     headless 截图输出 PNG",
    "  -t, --title TEXT    窗口标题",
    "      --ui-tour DIR   巡页模式（仅 --scene ui）：逐页/逐主题截图到 DIR",
    "      --tour-frames N 巡页每页等待帧数，默认 90",
    "",
    "  --scene vmap（真 vmap 组件）:",
    "      --vmap-viewport WxH     可视窗口尺寸（运行时生效），默认 = 屏幕",
    "      --vmap-center LON,LAT   地图中心（直接定位），默认板端开机中心",
    "      --vmap-scale S          连续缩放（z14 瓦片不换层），默认 1.69",
    "      --vmap-zoom Z           瓦片层级，默认 14",
    "      --vmap-icon dev|alt|none 中心图标：板端箭头 / 准星 / 不画",
    "      --vmap-pan DX,DY        首帧后脚本化平移（像素，验证拖动）",
    "      --vmap-resize WxH       首帧后**运行时**改 viewport 尺寸（验证 set_viewport）",
    "      --vmap-hud 0|1          HUD 开关，默认 1",
    "      --vmap-heading 0|1      航向朝上（R 缓冲旋转显示），默认 0",
    "      --vmap-course DEG       航向角（正北 0，顺时针），配合 --vmap-heading",
    "      --vmap-zoom-at X,Y,F    首帧后锚点缩放（可给两次），验证 zoom_at 锚点不动",
    "      --vmap-drag N,DX,DY     首帧后连续 N 次 pan_px(DX,DY)，验证亚像素累积",
    "      --vmap-icon-swap SRC    首帧后运行时换图（可给 3 次，dev|alt|none）",
    "      --vmap-recenter         拖动之后调 center_on() 回中（验证可回中、不弹回）",
    "      --vmap-follow N,M        首帧后喂 N 个 GNSS 点、每点东移 M 米（板端跟车热路径）",
    "      （窗口模式下：鼠标拖动 = 平移，滚轮 = 缩放；",
    "        按键 1/2/3 = 换图标，c = 轮换中心点，+/- = 缩放，r = 复位，f = 跟随开关）",
    "  -l, --list          列出所有场景",
    "  -h, --help          本帮助",
    NULL,
};

static void usage(void)
{
    for (int i = 0; kUsageLines[i]; i++) {
        puts(kUsageLines[i]);
    }
}

int main(int argc, char **argv)
{
    sim_cfg_t cfg;
    memset(&cfg, 0, sizeof(cfg));
    cfg.width = 240;
    cfg.height = 320;   /* 设备原生竖屏：状态栏 24 + 页面 296 */
    cfg.scale = 2;
    cfg.frames = 30;
    cfg.tour_frames = 90;
    cfg.title = "lvgl_sim";
    cfg.vmap_lon = NAN;   /* = 用组件默认中心 */
    cfg.vmap_lat = NAN;
    cfg.vmap_hud = true;

    const char *scene_name = "demo";
    bool list_only = false;

    enum {
        OPT_UI_TOUR = 256,
        OPT_TOUR_FRAMES,
        OPT_VMAP_VIEWPORT,
        OPT_VMAP_CENTER,
        OPT_VMAP_SCALE,
        OPT_VMAP_ZOOM,
        OPT_VMAP_ICON,
        OPT_VMAP_PAN,
        OPT_VMAP_RESIZE,
        OPT_VMAP_HUD,
        OPT_VMAP_HEADING,
        OPT_VMAP_COURSE,
        OPT_VMAP_ZOOM_AT,
        OPT_VMAP_DRAG,
        OPT_VMAP_ICON_SWAP,
        OPT_VMAP_RECENTER,
        OPT_VMAP_FOLLOW,
    };

    static const struct option long_opts[] = {
        { "scene",    required_argument, 0, 's' },
        { "size",     required_argument, 0, 'S' },
        { "scale",    required_argument, 0, 'k' },
        { "headless", no_argument,       0, 'H' },
        { "frames",   required_argument, 0, 'f' },
        { "shot",     required_argument, 0, 'o' },
        { "title",    required_argument, 0, 't' },
        { "ui-tour",  required_argument, 0, OPT_UI_TOUR },
        { "tour-frames", required_argument, 0, OPT_TOUR_FRAMES },
        { "vmap-viewport", required_argument, 0, OPT_VMAP_VIEWPORT },
        { "vmap-center", required_argument, 0, OPT_VMAP_CENTER },
        { "vmap-scale", required_argument, 0, OPT_VMAP_SCALE },
        { "vmap-zoom", required_argument, 0, OPT_VMAP_ZOOM },
        { "vmap-icon", required_argument, 0, OPT_VMAP_ICON },
        { "vmap-pan", required_argument, 0, OPT_VMAP_PAN },
        { "vmap-resize", required_argument, 0, OPT_VMAP_RESIZE },
        { "vmap-hud", required_argument, 0, OPT_VMAP_HUD },
        { "vmap-heading", required_argument, 0, OPT_VMAP_HEADING },
        { "vmap-course", required_argument, 0, OPT_VMAP_COURSE },
        { "vmap-zoom-at", required_argument, 0, OPT_VMAP_ZOOM_AT },
        { "vmap-drag", required_argument, 0, OPT_VMAP_DRAG },
        { "vmap-icon-swap", required_argument, 0, OPT_VMAP_ICON_SWAP },
        { "vmap-recenter", no_argument, 0, OPT_VMAP_RECENTER },
        { "vmap-follow", required_argument, 0, OPT_VMAP_FOLLOW },
        { "list",     no_argument,       0, 'l' },
        { "help",     no_argument,       0, 'h' },
        { NULL, 0, NULL, 0 },
    };

    int c;
    while ((c = getopt_long(argc, argv, "s:S:k:Hf:o:t:lh", long_opts, NULL)) != -1) {
        switch (c) {
            case 's': scene_name = optarg; break;
            case 'S':
                if (sscanf(optarg, "%dx%d", &cfg.width, &cfg.height) != 2) {
                    fprintf(stderr, "bad --size\n");
                    return 2;
                }
                break;
            case 'k': cfg.scale = atoi(optarg); break;
            case 'H': cfg.headless = true; break;
            case 'f': cfg.frames = atoi(optarg); break;
            case 'o': cfg.shot = optarg; break;
            case 't': cfg.title = optarg; break;
            case OPT_UI_TOUR: cfg.ui_tour = optarg; break;
            case OPT_TOUR_FRAMES: cfg.tour_frames = atoi(optarg); break;
            case OPT_VMAP_VIEWPORT:
                if (sscanf(optarg, "%dx%d", &cfg.vmap_w, &cfg.vmap_h) != 2) {
                    fprintf(stderr, "bad --vmap-viewport (want WxH)\n");
                    return 2;
                }
                break;
            case OPT_VMAP_CENTER:
                if (sscanf(optarg, "%lf,%lf", &cfg.vmap_lon, &cfg.vmap_lat) != 2) {
                    fprintf(stderr, "bad --vmap-center (want LON,LAT)\n");
                    return 2;
                }
                break;
            case OPT_VMAP_SCALE: cfg.vmap_scale = atof(optarg); break;
            case OPT_VMAP_ZOOM: cfg.vmap_zoom = atoi(optarg); break;
            case OPT_VMAP_ICON:
                if (strcmp(optarg, "dev") == 0) {
                    cfg.vmap_icon = SIM_VMAP_ICON_DEV;
                } else if (strcmp(optarg, "alt") == 0) {
                    cfg.vmap_icon = SIM_VMAP_ICON_ALT;
                } else if (strcmp(optarg, "none") == 0) {
                    cfg.vmap_icon = SIM_VMAP_ICON_NONE;
                } else {
                    fprintf(stderr, "bad --vmap-icon (dev|alt|none)\n");
                    return 2;
                }
                break;
            case OPT_VMAP_PAN:
                if (sscanf(optarg, "%d,%d", &cfg.vmap_pan_x, &cfg.vmap_pan_y) != 2) {
                    fprintf(stderr, "bad --vmap-pan (want DX,DY)\n");
                    return 2;
                }
                cfg.vmap_pan_set = true;
                break;
            case OPT_VMAP_RESIZE:
                if (sscanf(optarg, "%dx%d", &cfg.vmap_rw, &cfg.vmap_rh) != 2) {
                    fprintf(stderr, "bad --vmap-resize (want WxH)\n");
                    return 2;
                }
                break;
            case OPT_VMAP_HUD: cfg.vmap_hud = atoi(optarg) != 0; break;
            case OPT_VMAP_HEADING: cfg.vmap_heading = atoi(optarg) != 0; break;
            case OPT_VMAP_COURSE: cfg.vmap_course = atof(optarg); break;
            case OPT_VMAP_ZOOM_AT:
                if (cfg.vmap_zoom_at_n >= 2) {
                    fprintf(stderr, "bad --vmap-zoom-at (max 2)\n");
                    return 2;
                }
                {
                    const int i = cfg.vmap_zoom_at_n;

                    if (sscanf(optarg, "%d,%d,%lf", &cfg.vmap_za_x[i],
                            &cfg.vmap_za_y[i], &cfg.vmap_za_f[i]) != 3 || cfg.vmap_za_f[i] <= 0.0) {
                        fprintf(stderr, "bad --vmap-zoom-at (want X,Y,FACTOR)\n");
                        return 2;
                    }
                }
                cfg.vmap_zoom_at_n++;
                break;
            case OPT_VMAP_RECENTER: cfg.vmap_recenter = true; break;
            case OPT_VMAP_FOLLOW:
                if (sscanf(optarg, "%d,%lf", &cfg.vmap_follow_n, &cfg.vmap_follow_m) != 2
                    || cfg.vmap_follow_n <= 0 || !(cfg.vmap_follow_m > 0.0)) {
                    fprintf(stderr, "bad --vmap-follow (want N,METERS)\n");
                    return 2;
                }
                break;
            case OPT_VMAP_ICON_SWAP: {
                int icon;

                if (strcmp(optarg, "dev") == 0) {
                    icon = SIM_VMAP_ICON_DEV;
                } else if (strcmp(optarg, "alt") == 0) {
                    icon = SIM_VMAP_ICON_ALT;
                } else if (strcmp(optarg, "none") == 0) {
                    icon = SIM_VMAP_ICON_NONE;
                } else {
                    fprintf(stderr, "bad --vmap-icon-swap (dev|alt|none)\n");
                    return 2;
                }
                if (cfg.vmap_swap_n >= 3) {
                    fprintf(stderr, "bad --vmap-icon-swap (max 3)\n");
                    return 2;
                }
                cfg.vmap_swap_icon[cfg.vmap_swap_n++] = icon;
                break;
            }
            case OPT_VMAP_DRAG:
                if (sscanf(optarg, "%d,%d,%d", &cfg.vmap_drag_n,
                        &cfg.vmap_drag_x, &cfg.vmap_drag_y) != 3 || cfg.vmap_drag_n <= 0) {
                    fprintf(stderr, "bad --vmap-drag (want N,DX,DY)\n");
                    return 2;
                }
                break;
            case 'l': list_only = true; break;
            case 'h': usage(); return 0;
            default: usage(); return 2;
        }
    }

    if (list_only) {
        sim_scene_list();
        return 0;
    }

    const sim_scene_t *scene = sim_scene_find(scene_name);
    if (!scene) {
        fprintf(stderr, "unknown scene\n");
        sim_scene_list();
        return 2;
    }

    lv_init();
    lv_tick_set_cb(cfg.headless ? vtick_get : sim_tick_ms);

    if (!sim_display_init(&cfg)) {
        return 1;
    }
    sim_lvgl_bind();

    scene->create(lv_screen_active(), &cfg);
    printf("lvgl_sim: scene=%s %dx%d scale=%d %s\n", scene->name, cfg.width,
           cfg.height, cfg.scale, cfg.headless ? "headless" : "window");

    if (cfg.ui_tour != NULL && cfg.tour_frames <= 0) {
        cfg.tour_frames = 90;
    }

    if (cfg.headless) {
        /* 巡页模式下帧数由巡页状态机自己决定，这里只给一个死循环保护。
         * 只有 `ui` 场景会真正启用巡页（见 scenes.c）；其它场景带 --ui-tour
         * 也完全按原来的 --frames 跑。 */
        int frames = cfg.frames;

#ifdef SIM_WITH_UI
        const bool tour = sim_ui_tour_enabled();

        if (tour) {
            frames = 6000;
        }
#endif
        for (int i = 0; i < frames; i++) {
            s_vtick += 16;
            lv_timer_handler();
#ifdef SIM_WITH_UI
            if (tour && sim_ui_tour_done()) {
                break;
            }
            /* WP-FADE/R1 临时探针跑完即退出（未启用时恒为 false）。 */
            if (sim_ui_fade_probe_done()) {
                break;
            }
#endif
        }
        if (cfg.shot) {
            int w = 0;
            int h = 0;
            const uint16_t *fb = sim_display_shadow(&w, &h);

            if (!sim_png_write(cfg.shot, fb, w, h)) {
                fprintf(stderr, "failed to write png\n");
                sim_display_shutdown();
                return 1;
            }
            printf("shot -> %s (%dx%d)\n", cfg.shot, w, h);
        }
    } else {
        while (sim_display_pump()) {
            uint32_t idle = lv_timer_handler();

#ifdef SIM_WITH_UI
            if (sim_ui_tour_enabled() && sim_ui_tour_done()) {
                break;
            }
#endif
            if (idle < 1) {
                idle = 1;
            }
            if (idle > 16) {
                idle = 16;
            }
            usleep(idle * 1000);
        }
    }

    sim_display_shutdown();
    return 0;
}

/**
 * @file sim_display.c
 * @brief X11 窗口 + LVGL display/indev 绑定；headless 下只维护影子帧缓冲。
 *
 * 为什么不照搬 lv_port_linux：那个工程是 Kconfig/CMake 组件化的，源文件
 * 依赖它的 SDK 框架。这里只要"一块 RGB565 画布 + 鼠标键盘"，自己写
 * 200 行比拖一整套框架干净，而且窗口缩放、headless 截图都能自己控制。
 */

#define _POSIX_C_SOURCE 199309L

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#include <X11/Xlib.h>
#include <X11/Xutil.h>
#include <X11/keysym.h>

#include "sim.h"

static struct {
    Display *dpy;
    Window win;
    GC gc;
    XImage *img;
    Atom wm_delete;
    int w, h, scale;
    bool headless;
    bool quit;

    int mx, my;
    bool pressed;

    lv_group_t *group;
    lv_indev_t *indev_ptr;
    lv_indev_t *indev_key;

    uint32_t keys[32];
    int key_head, key_tail;
    uint32_t last_key;

    /* `vmap` 场景用的附加输入通道（其它场景不消费）：
     * 滚轮是"格数"累计，原始按键是给场景直接轮询的 ASCII。 */
    int wheel;
    char raw_keys[32];
    int raw_head, raw_tail;

    uint16_t *shadow;   /* 整帧影子：Expose 重画 + headless 截图都靠它 */
} s;

uint32_t sim_tick_ms(void)
{
    struct timespec ts;

    clock_gettime(CLOCK_MONOTONIC, &ts);
    return (uint32_t)((uint64_t)ts.tv_sec * 1000u + (uint64_t)ts.tv_nsec / 1000000u);
}

static inline uint32_t rgb565_to_xrgb(uint16_t c)
{
    uint32_t r = (uint32_t)((c >> 11) & 0x1Fu);
    uint32_t g = (uint32_t)((c >> 5) & 0x3Fu);
    uint32_t b = (uint32_t)(c & 0x1Fu);

    r = (r << 3) | (r >> 2);
    g = (g << 2) | (g >> 4);
    b = (b << 3) | (b >> 2);
    return (r << 16) | (g << 8) | b;
}

/* 把影子缓冲的一块画到窗口（只画脏矩形，缩放用最近邻）。 */
static void blit_rect(int x0, int y0, int w, int h)
{
    if (s.headless || !s.dpy || !s.img) {
        return;
    }

    const int sc = s.scale;
    const int iw = s.w * sc;
    const bool fast = (s.img->bits_per_pixel == 32);

    for (int y = 0; y < h; y++) {
        const uint16_t *src = s.shadow + (size_t)(y0 + y) * (size_t)s.w + x0;
        for (int sy = 0; sy < sc; sy++) {
            int row = (y0 + y) * sc + sy;
            for (int x = 0; x < w; x++) {
                uint32_t rgb = rgb565_to_xrgb(src[x]);
                for (int sx = 0; sx < sc; sx++) {
                    int col = (x0 + x) * sc + sx;
                    if (fast) {
                        ((uint32_t *)s.img->data)[(size_t)row * (size_t)iw + col] = rgb;
                    } else {
                        XPutPixel(s.img, col, row, rgb);
                    }
                }
            }
        }
    }
    XPutImage(s.dpy, s.win, s.gc, s.img, x0 * sc, y0 * sc, x0 * sc, y0 * sc,
              (unsigned)w * (unsigned)sc, (unsigned)h * (unsigned)sc);
    XFlush(s.dpy);
}

/* ── LVGL flush ────────────────────────────────────────────────── */

static void flush_cb(lv_display_t *disp, const lv_area_t *area, uint8_t *px_map)
{
    const int w = (int)lv_area_get_width(area);
    const int h = (int)lv_area_get_height(area);
    const uint16_t *px = (const uint16_t *)px_map;

    for (int y = 0; y < h; y++) {
        memcpy(s.shadow + (size_t)(area->y1 + y) * (size_t)s.w + area->x1,
               px + (size_t)y * (size_t)w, (size_t)w * 2u);
    }
    blit_rect(area->x1, area->y1, w, h);
    lv_display_flush_ready(disp);
}
/* ── 输入 ──────────────────────────────────────────────────────── */

static void pointer_read(lv_indev_t *indev, lv_indev_data_t *data)
{
    (void)indev;
    data->point.x = (int32_t)s.mx;
    data->point.y = (int32_t)s.my;
    data->state = s.pressed ? LV_INDEV_STATE_PRESSED : LV_INDEV_STATE_RELEASED;
}

static void key_push(uint32_t key)
{
    int next = (s.key_tail + 1) % (int)(sizeof(s.keys) / sizeof(s.keys[0]));

    if (next == s.key_head) {
        return;
    }
    s.keys[s.key_tail] = key;
    s.key_tail = next;
}

static void keypad_read(lv_indev_t *indev, lv_indev_data_t *data)
{
    (void)indev;
    if (s.key_head != s.key_tail) {
        s.last_key = s.keys[s.key_head];
        s.key_head = (s.key_head + 1) % (int)(sizeof(s.keys) / sizeof(s.keys[0]));
        data->state = LV_INDEV_STATE_PRESSED;
    } else {
        data->state = LV_INDEV_STATE_RELEASED;
    }
    data->key = s.last_key;
}

static void raw_key_push(char k)
{
    int next = (s.raw_tail + 1) % (int)(sizeof(s.raw_keys) / sizeof(s.raw_keys[0]));

    if (next == s.raw_head) {
        return;
    }
    s.raw_keys[s.raw_tail] = k;
    s.raw_tail = next;
}

int sim_display_take_wheel(void)
{
    const int n = s.wheel;

    s.wheel = 0;
    return n;
}

int sim_display_take_raw_key(void)
{
    if (s.raw_head == s.raw_tail) {
        return 0;
    }
    {
        const char k = s.raw_keys[s.raw_head];

        s.raw_head = (s.raw_head + 1) % (int)(sizeof(s.raw_keys) / sizeof(s.raw_keys[0]));
        return k;
    }
}

static uint32_t xkey_to_lv(KeySym ks)
{
    switch (ks) {
        case XK_Left:  return LV_KEY_LEFT;
        case XK_Right: return LV_KEY_RIGHT;
        case XK_Up:    return LV_KEY_UP;
        case XK_Down:  return LV_KEY_DOWN;
        case XK_Return:
        case XK_KP_Enter: return LV_KEY_ENTER;
        case XK_Escape:   return LV_KEY_ESC;
        case XK_BackSpace:return LV_KEY_BACKSPACE;
        case XK_Tab:      return LV_KEY_NEXT;
        case XK_Home:     return LV_KEY_HOME;
        case XK_End:      return LV_KEY_END;
        default: return 0;
    }
}

lv_group_t *sim_input_group(void)
{
    if (!s.group) {
        s.group = lv_group_create();
        lv_group_set_default(s.group);
    }
    return s.group;
}

/* ── 事件循环 ──────────────────────────────────────────────────── */

bool sim_display_pump(void)
{
    if (s.headless || !s.dpy) {
        return !s.quit;
    }

    while (XPending(s.dpy)) {
        XEvent ev;

        XNextEvent(s.dpy, &ev);
        switch (ev.type) {
            case Expose:
                if (ev.xexpose.count == 0) {
                    blit_rect(0, 0, s.w, s.h);
                }
                break;
            case MotionNotify:
                s.mx = ev.xmotion.x / s.scale;
                s.my = ev.xmotion.y / s.scale;
                if (s.mx < 0) s.mx = 0;
                if (s.my < 0) s.my = 0;
                if (s.mx > s.w - 1) s.mx = s.w - 1;
                if (s.my > s.h - 1) s.my = s.h - 1;
                break;
            case ButtonPress:
                if (ev.xbutton.button == Button1) {
                    s.pressed = true;
                } else if (ev.xbutton.button == Button4) {
                    s.wheel++;      /* 滚轮上 = 放大 */
                } else if (ev.xbutton.button == Button5) {
                    s.wheel--;      /* 滚轮下 = 缩小 */
                }
                break;
            case ButtonRelease:
                if (ev.xbutton.button == Button1) {
                    s.pressed = false;
                }
                break;
            case KeyPress: {
                KeySym ks = XLookupKeysym(&ev.xkey, 0);
                uint32_t key = xkey_to_lv(ks);

                if (key) {
                    key_push(key);
                }
                /* `vmap` 场景的快捷键（其它场景不轮询，等于不存在）。 */
                switch (ks) {
                    case XK_1: raw_key_push('1'); break;
                    case XK_2: raw_key_push('2'); break;
                    case XK_3: raw_key_push('3'); break;
                    case XK_r: raw_key_push('r'); break;
                    case XK_f: raw_key_push('f'); break;
                    case XK_i: raw_key_push('i'); break;
                    case XK_c: raw_key_push('c'); break;
                    case XK_plus: case XK_equal: case XK_KP_Add:
                        raw_key_push('+');
                        break;
                    case XK_minus: case XK_KP_Subtract:
                        raw_key_push('-');
                        break;
                    default:
                        break;
                }
                break;
            }
            case ClientMessage:
                if ((Atom)ev.xclient.data.l[0] == s.wm_delete) {
                    s.quit = true;
                }
                break;
            case DestroyNotify:
                s.quit = true;
                break;
            default:
                break;
        }
    }
    return !s.quit;
}

/* ── 初始化 ────────────────────────────────────────────────────── */

static bool shadow_alloc(void)
{
    s.shadow = calloc((size_t)s.w * (size_t)s.h, sizeof(uint16_t));
    if (!s.shadow) {
        fprintf(stderr, "sim: out of memory for shadow framebuffer\n");
        return false;
    }
    for (size_t i = 0; i < (size_t)s.w * (size_t)s.h; i++) {
        s.shadow[i] = 0xFFFF;
    }
    return true;
}

static bool window_open(const sim_cfg_t *cfg)
{
    const int scr = DefaultScreen(s.dpy);
    const int win_w = s.w * s.scale;
    const int win_h = s.h * s.scale;

    s.win = XCreateSimpleWindow(s.dpy, RootWindow(s.dpy, scr), 0, 0,
                                (unsigned)win_w, (unsigned)win_h, 0,
                                BlackPixel(s.dpy, scr), WhitePixel(s.dpy, scr));
    XStoreName(s.dpy, s.win, cfg->title ? cfg->title : "lvgl_sim");

    XSizeHints hints;
    memset(&hints, 0, sizeof(hints));
    hints.flags = PMinSize | PMaxSize;
    hints.min_width = hints.max_width = win_w;
    hints.min_height = hints.max_height = win_h;
    XSetWMNormalHints(s.dpy, s.win, &hints);

    s.wm_delete = XInternAtom(s.dpy, "WM_DELETE_WINDOW", False);
    XSetWMProtocols(s.dpy, s.win, &s.wm_delete, 1);

    XSelectInput(s.dpy, s.win,
                 ExposureMask | ButtonPressMask | ButtonReleaseMask |
                 PointerMotionMask | KeyPressMask | StructureNotifyMask);

    s.gc = XCreateGC(s.dpy, s.win, 0, NULL);

    s.img = XCreateImage(s.dpy, DefaultVisual(s.dpy, scr),
                         (unsigned)DefaultDepth(s.dpy, scr), ZPixmap, 0, NULL,
                         (unsigned)win_w, (unsigned)win_h, 32, 0);
    if (!s.img) {
        fprintf(stderr, "sim: XCreateImage failed\n");
        return false;
    }
    s.img->data = calloc((size_t)s.img->bytes_per_line, (size_t)win_h);
    if (!s.img->data) {
        fprintf(stderr, "sim: out of memory for XImage\n");
        return false;
    }

    XMapWindow(s.dpy, s.win);
    XFlush(s.dpy);

    if (s.img->bits_per_pixel != 32) {
        fprintf(stderr, "sim: warning: X server is %d bpp, using slow XPutPixel path\n",
                s.img->bits_per_pixel);
    }
    return true;
}

bool sim_display_init(const sim_cfg_t *cfg)
{
    s.w = cfg->width > 0 ? cfg->width : 240;
    s.h = cfg->height > 0 ? cfg->height : 400;
    s.scale = cfg->scale > 0 ? cfg->scale : 2;
    s.headless = cfg->headless;
    s.quit = false;

    if (!shadow_alloc()) {
        return false;
    }
    if (s.headless) {
        return true;
    }

    s.dpy = XOpenDisplay(NULL);
    if (!s.dpy) {
        fprintf(stderr, "sim: cannot open X display; use --headless --shot out.png\n");
        return false;
    }
    return window_open(cfg);
}

void sim_lvgl_bind(void)
{
    /* 两个 1/10 屏的局部缓冲：和设备的渲染模式一致，刷新时只送脏矩形 */
    const uint32_t stride = (uint32_t)s.w;
    const uint32_t lines = 40;
    const uint32_t bytes = stride * lines * 2u;
    void *buf1 = lv_malloc(bytes);
    void *buf2 = lv_malloc(bytes);

    lv_display_t *disp = lv_display_create(s.w, s.h);

    lv_display_set_flush_cb(disp, flush_cb);
    lv_display_set_buffers(disp, buf1, buf2, bytes, LV_DISPLAY_RENDER_MODE_PARTIAL);
    lv_display_set_default(disp);

    s.indev_ptr = lv_indev_create();
    lv_indev_set_type(s.indev_ptr, LV_INDEV_TYPE_POINTER);
    lv_indev_set_read_cb(s.indev_ptr, pointer_read);

    s.indev_key = lv_indev_create();
    lv_indev_set_type(s.indev_key, LV_INDEV_TYPE_KEYPAD);
    lv_indev_set_read_cb(s.indev_key, keypad_read);
    lv_indev_set_group(s.indev_key, sim_input_group());
}

const uint16_t *sim_display_shadow(int *w, int *h)
{
    if (w) *w = s.w;
    if (h) *h = s.h;
    return s.shadow;
}

void sim_display_shutdown(void)
{
    if (s.img) {
        /* XDestroyImage 会 free(data) */
        XDestroyImage(s.img);
        s.img = NULL;
    }
    if (s.gc && s.dpy) {
        XFreeGC(s.dpy, s.gc);
        s.gc = NULL;
    }
    if (s.win && s.dpy) {
        XDestroyWindow(s.dpy, s.win);
        s.win = 0;
    }
    if (s.dpy) {
        XCloseDisplay(s.dpy);
        s.dpy = NULL;
    }
    free(s.shadow);
    s.shadow = NULL;
}

/**
 * @file helm_font.c
 * @brief 菜单/标题用 MiSans 4bpp 点阵，链尾统一挂系统 TTF 兜底缺字。
 *
 * 点阵字库只覆盖 582 个码位（`helm_mism4_*` ∪ `helm_ui_*` 回退，2026-10-01 用
 * 生成文件里的 cmap 实测），用户自己的轨迹文件名、蓝牙设备名、任意 App 的通知
 * 正文必然落在库外；而本工程开了 `LV_USE_FONT_PLACEHOLDER` ⇒ 查不到的字画的是
 * **方块**，现场读作"乱码"。
 *
 * 所以每条链都按 `点阵 → 苹方点阵 → 系统 TTF` 排。LVGL 只在前面查不到时才往
 * `fallback` 走（`lv_font.c` 的 `while(f)` 循环），常见字仍走点阵、不增加
 * FreeType 光栅化开销，外来字才落到系统矢量字。
 *
 * 启动顺序：TTF 由 startup 分片预载，菜单第一次构建时**可能还没就绪**，所以链尾
 * 由 helm_font_sync_sys() 后补。补的是本文件自己的 `s_*_fb` 结构体，已经建好的
 * label 持有的正是它们的地址 ⇒ 补完即生效，不需要重建对象。
 *
 * @warning **绝不**能把 `fallback` 写进 `myvendor_system_font_get()` 返回的字体：
 *          那是所有调用方共用的缓存槽，写进去会互相污染（见 helm_font.h）。
 */

#include "helm_font.h"

#include <stdbool.h>

/** @brief 三档字号，各两层：点阵本体 + 苹方点阵（链尾留给 TTF）。 */
static lv_font_t s_lab;
static lv_font_t s_lab_fb;
static lv_font_t s_title;
static lv_font_t s_title_fb;
static lv_font_t s_val;
static lv_font_t s_val_fb;
/** @brief 状态栏用 12px 苹方（不含 MiSans 层，保持原观感）。 */
static lv_font_t s_status;
static bool s_ready;
/** @brief 链尾 TTF 是否已全部接好；没接好时每次取字体都重试。 */
static bool s_sys_linked;

/** @brief 给一档点阵补上行尾 TTF（已接过的跳过，避免重复占引用）。 */
static void helm_font_link_one(lv_font_t * fb, int32_t px)
{
    if (fb->fallback == NULL) {
        fb->fallback = myvendor_system_font_get(px);
    }
}

void helm_font_sync_sys(void)
{
    if (s_sys_linked || !myvendor_system_font_preloaded()) {
        return;
    }

    helm_font_link_one(&s_lab_fb, 12);
    helm_font_link_one(&s_title_fb, 15);
    helm_font_link_one(&s_val_fb, 22);
    helm_font_link_one(&s_status, 12);

    /* 四档只要还剩一档没挂上就继续重试；TTF 缺失 / 工厂固件时这里恒为假，
     * 链保持纯点阵 —— 与改动前同行为。 */
    s_sys_linked = (s_lab_fb.fallback != NULL && s_title_fb.fallback != NULL &&
                    s_val_fb.fallback != NULL && s_status.fallback != NULL);
}

static void helm_font_init(void)
{
    if (s_ready) {
        return;
    }

    s_lab = helm_mism4_12;
    s_lab_fb = helm_ui_12;
    s_lab.fallback = &s_lab_fb;

    s_title = helm_mism4_15;
    s_title_fb = helm_ui_15;
    s_title.fallback = &s_title_fb;

    s_val = helm_mism4_22;
    s_val_fb = helm_ui_22;
    s_val.fallback = &s_val_fb;

    /* 状态栏只要苹方一层（观感与改动前逐像素一致），链尾由 sync 补 TTF。 */
    s_status = helm_ui_12;
    s_status.fallback = NULL;

    s_ready = true;
    helm_font_sync_sys();
}

const lv_font_t * helm_font_lab(void)
{
    helm_font_init();
    helm_font_sync_sys();
    return &s_lab;
}

const lv_font_t * helm_font_title(void)
{
    helm_font_init();
    helm_font_sync_sys();
    return &s_title;
}

const lv_font_t * helm_font_val(void)
{
    helm_font_init();
    helm_font_sync_sys();
    return &s_val;
}

const lv_font_t * helm_font_status(void)
{
    helm_font_init();
    helm_font_sync_sys();
    return &s_status;
}
