{"content": "/**
 * @file scene_design_b.c
 * @brief WP-DESIGN 方案 B「数据仪表」：近黑底、等宽右对齐数字、3px 色条分栏、
 *        20px 窄状态栏、底部区间条、单一青绿强调色。
 *
 * 三个屏幕由 SIM_DESIGN_SCREEN=standby|ride|menu 选择（见 design_common.h）。
 * 纯 LVGL 控件：obj/label/line，无位图、无自定义 draw。
 */

#include "design_common.h"

/* ── 色板（近黑 / 单一青绿）────────────────────────────────────── */
#define B_BG      0x0B0C0Eu   /**< 近黑底 */
#define B_TEXT    0xF4F7F8u   /**< 主数据 */
#define B_MID     0xB9C2C9u   /**< 次级正文 */
#define B_DIM     0x7C858Eu   /**< 标签 */
#define B_DIM2    0x3A4249u   /**< 非活动色条 / 刻度 */
#define B_LINE    0x1E2328u   /**< 分隔线 */
#define B_TRACK   0x1B2025u   /**< 进度底 */
#define B_ACCENT  0x00D1B2u   /**< 唯一强调色（青绿） */
#define B_SEL     0x0F181Au   /**< 选中行底 */

static void b_hline(lv_obj_t *p, int x, int y, int w)
{
    d_hline(p, x, y, w, B_LINE, LV_OPA_COVER);
}

/** 20px 窄状态栏：左标题、右 GPS。 */
static void b_status(lv_obj_t *scr, const char *left, const char *right, bool gps)
{
    d_label(scr, left, 10, B_MID, 12, 2);
    if (gps) {
        d_dot(scr, 172, 8, 4, B_ACCENT);
        d_label_w(scr, right, 10, B_DIM, 180, 2, 48, LV_TEXT_ALIGN_RIGHT);
    } else {
        d_label_w(scr, right, 10, B_DIM, 140, 2, 88, LV_TEXT_ALIGN_RIGHT);
    }
    b_hline(scr, 0, 20, 240);
}

/** 细进度条。 */
static void b_bar(lv_obj_t *p, int x, int y, int w, int h, int pct,
                  uint32_t fill, uint32_t track)
{
    int fw = w * pct / 100;

    d_box(p, x, y, w, h, track, LV_OPA_COVER, h / 2);
    if (fw > 0) {
        d_box(p, x, y, fw, h, fill, LV_OPA_COVER, h / 2);
    }
}

/** 数据块：3px 色条 + 左标签 + 右对齐数值/单位。 */
static void b_metric(lv_obj_t *p, int x, int y, int w,
                     const char *label, const char *val, const char *unit,
                     bool active)
{
    d_box(p, x, y + 2, 3, 24, active ? B_ACCENT : B_DIM2, LV_OPA_COVER, 0);
    d_label(p, label, 10, B_DIM, x + 10, y + 6);

    lv_obj_t *row = d_stack(p, x + 34, y + 1, w - 40, 28, LV_FLEX_ALIGN_END, 4);
    lv_obj_t *v = lv_label_create(row);

    lv_label_set_text(v, val);
    lv_obj_set_style_text_font(v, sim_font_cjk(20), 0);
    lv_obj_set_style_text_color(v, lv_color_hex(active ? B_ACCENT : B_TEXT), 0);
    lv_obj_set_style_text_letter_space(v, -0.5, 0);

    if (unit && unit[0]) {
        lv_obj_t *u = lv_label_create(row);

        lv_label_set_text(u, unit);
        lv_obj_set_style_text_font(u, sim_font_cjk(9), 0);
        lv_obj_set_style_text_color(u, lv_color_hex(B_DIM), 0);
        lv_obj_set_style_pad_bottom(u, 3, 0);
    }
}

/** 图标位：18x18 细描边方 + 内部几何形。 */
static void b_icon(lv_obj_t *p, int x, int y, int kind, uint32_t color)
{
    lv_obj_t *box = d_box(p, x, y, 18, 18, 0x000000u, LV_OPA_TRANSP, 4);

    lv_obj_set_style_border_width(box, 1, 0);
    lv_obj_set_style_border_color(box, lv_color_hex(color), 0);
    lv_obj_set_style_border_opa(box, LV_OPA_COVER, 0);

    switch (kind) {
        case 0: d_box(box, 6, 6, 6, 6, color, LV_OPA_COVER, 3); break;
        case 1: d_box(box, 5, 5, 8, 8, color, LV_OPA_40, 4); break;
        case 2: d_box(box, 5, 6, 8, 6, color, LV_OPA_COVER, 1); break;
        default: d_box(box, 8, 4, 2, 10, color, LV_OPA_COVER, 1); break;
    }
}

/* ── 待机 ──────────────────────────────────────────────────────── */

static void b_standby(lv_obj_t *scr)
{
    d_bg(scr, B_BG);
    b_status(scr, "待机", "GPS 12", true);

    d_label(scr, "10月29日 星期四", 12, B_DIM, 12, 28);

    /* 当前时间：数据块 + 右对齐 64px */
    d_box(scr, 12, 56, 3, 80, B_ACCENT, LV_OPA_COVER, 0);
    d_label(scr, "当前时间", 10, B_DIM, 24, 54);
    lv_obj_t *trow = d_stack(scr, 22, 66, 206, 74, LV_FLEX_ALIGN_END, 0);
    lv_obj_t *time = lv_label_create(trow);

    lv_label_set_text(time, "08:42");
    lv_obj_set_style_text_font(time, sim_font_cjk(64), 0);
    lv_obj_set_style_text_color(time, lv_color_hex(B_TEXT), 0);
    lv_obj_set_style_text_letter_space(time, -1, 0);

    b_hline(scr, 12, 146, 216);

    /* 上次骑行 */
    d_box(scr, 12, 160, 3, 60, B_DIM2, LV_OPA_COVER, 0);
    d_label(scr, "上次骑行", 10, B_DIM, 24, 158);
    lv_obj_t *lrow = d_stack(scr, 24, 174, 176, 30, LV_FLEX_ALIGN_END, 4);
    lv_obj_t *lv = lv_label_create(lrow);

    lv_label_set_text(lv, "42.6");
    lv_obj_set_style_text_font(lv, sim_font_cjk(34), 0);
    lv_obj_set_style_text_color(lv, lv_color_hex(B_TEXT), 0);
    lv_obj_set_style_text_letter_space(lv, -0.5, 0);
    lv_obj_t *lu = lv_label_create(lrow);

    lv_label_set_text(lu, "KM");
    lv_obj_set_style_text_font(lu, sim_font_cjk(9), 0);
    lv_obj_set_style_text_color(lu, lv_color_hex(B_DIM), 0);
    lv_obj_set_style_pad_bottom(lu, 5, 0);

    d_label(scr, "用时 1:52:03 · 均速 26.4 KM/H", 10, B_DIM, 24, 212);

    /* 本周目标 */
    d_label(scr, "本周里程", 10, B_DIM, 12, 246);
    d_label_w(scr, "68 / 100 KM", 10, B_DIM, 128, 246, 100, LV_TEXT_ALIGN_RIGHT);
    b_bar(scr, 12, 262, 216, 8, 68, B_ACCENT, B_TRACK);

    b_hline(scr, 12, 280, 216);

    d_label(scr, "长按 KEY2  开始骑行", 12, B_ACCENT, 12, 290);
    d_label_w(scr, "短按 KEY1  菜单", 11, B_DIM, 120, 291, 108, LV_TEXT_ALIGN_RIGHT);
}

/* ── 骑行 ──────────────────────────────────────────────────────── */

static void b_ride(lv_obj_t *scr)
{
    d_bg(scr, B_BG);

    d_dot(scr, 12, 9, 4, B_ACCENT);
    d_label(scr, "骑行中", 10, B_TEXT, 20, 2);
    d_label_w(scr, "00:42:18", 10, B_DIM, 160, 2, 68, LV_TEXT_ALIGN_RIGHT);
    b_hline(scr, 0, 20, 240);

    /* 时速 */
    d_box(scr, 12, 34, 3, 86, B_ACCENT, LV_OPA_COVER, 0);
    d_label(scr, "时速  SPEED", 10, B_DIM, 24, 32);
    lv_obj_t *srow = d_stack(scr, 22, 44, 176, 76, LV_FLEX_ALIGN_END, 0);
    lv_obj_t *spd = lv_label_create(srow);

    lv_label_set_text(spd, "24.8");
    lv_obj_set_style_text_font(spd, sim_font_cjk(64), 0);
    lv_obj_set_style_text_color(spd, lv_color_hex(B_TEXT), 0);
    lv_obj_set_style_text_letter_space(spd, -1, 0);
    d_label(scr, "KM/H", 10, B_DIM, 202, 102);

    /* 速度区间条：0..60，每 20% 一格 */
    b_bar(scr, 12, 136, 216, 6, 41, B_ACCENT, B_TRACK);
    for (int i = 1; i < 5; i++) {
        d_vline(scr, 12 + 216 * i / 5, 134, 10, B_BG, LV_OPA_COVER);
    }
    d_label(scr, "0", 9, B_DIM, 12, 146);
    d_label_w(scr, "60", 9, B_DIM, 208, 146, 20, LV_TEXT_ALIGN_RIGHT);

    /* 2x3 数据块 */
    b_metric(scr, 12, 162, 106, "里程", "12.4", "KM", false);
    b_metric(scr, 122, 162, 106, "时间", "42:18", "", false);
    b_metric(scr, 12, 194, 106, "心率", "142", "BPM", true);
    b_metric(scr, 122, 194, 106, "踏频", "86", "RPM", false);
    b_metric(scr, 12, 226, 106, "海拔", "326", "M", false);
    b_metric(scr, 122, 226, 106, "坡度", "3.2", "%", false);

    /* 底部区间条 */
    d_label(scr, "区间 3 · 有氧", 10, B_DIM, 12, 260);
    d_label_w(scr, "46% FTP", 10, B_ACCENT, 150, 260, 78, LV_TEXT_ALIGN_RIGHT);
    for (int i = 0; i < 5; i++) {
        const int sx = 12 + i * 43;

        d_box(scr, sx, 274, 42, 10,
              i == 2 ? B_ACCENT : (i < 2 ? 0x22403B : B_TRACK), LV_OPA_COVER, 2);
    }

    d_label(scr, "短按 KEY1  切换", 11, B_MID, 12, 294);
    d_label_w(scr, "长按 KEY2  结束", 12, B_ACCENT, 116, 292, 112,
              LV_TEXT_ALIGN_RIGHT);
}

/* ── 菜单 ──────────────────────────────────────────────────────── */

typedef struct {
    const char *group;
    const char *item[2];
    const char *value[2];
    int icon[2];
} b_group_t;

static void b_menu_group(lv_obj_t *scr, int y, const b_group_t *g, int sel)
{
    d_box(scr, 12, y + 6, 6, 2, B_DIM2, LV_OPA_COVER, 0);
    d_label(scr, g->group, 10, B_DIM, 22, y);
    for (int i = 0; i < 2; i++) {
        const int ry = y + 14 + i * 29;
        const bool on = (sel == i);

        if (on) {
            d_box(scr, 8, ry, 224, 28, B_SEL, LV_OPA_COVER, 5);
            d_box(scr, 8, ry + 3, 3, 22, B_ACCENT, LV_OPA_COVER, 0);
        } else {
            d_box(scr, 8, ry + 3, 3, 22, B_DIM2, LV_OPA_COVER, 0);
            b_hline(scr, 44, ry + 28, 184);
        }
        b_icon(scr, 18, ry + 5, g->icon[i], on ? B_ACCENT : B_DIM2);
        d_label(scr, g->item[i], 13, on ? B_TEXT : B_MID, 44, ry + 5);
        if (g->value[i] && g->value[i][0]) {
            d_label_w(scr, g->value[i], 10, on ? B_ACCENT : B_DIM,
                      140, ry + 9, 68, LV_TEXT_ALIGN_RIGHT);
        }
        d_chevron(scr, 214, ry + 9, on ? B_ACCENT : B_DIM2, 8);
    }
}

static void b_menu(lv_obj_t *scr)
{
    static const b_group_t route = { "路线", { "路线规划", "历史记录" },
                                     { "3 条", "26 次" }, { 0, 1 } };
    static const b_group_t dev = { "设备", { "传感器", "显示" },
                                   { "已连接", "自动" }, { 2, 3 } };
    static const b_group_t sys = { "系统", { "关于", "关机" },
                                   { "v1.2", "" }, { 1, 0 } };

    d_bg(scr, B_BG);
    b_status(scr, "菜单", "6 项", false);

    d_label(scr, "设置", 20, B_TEXT, 12, 26);
    d_label_w(scr, "SETTINGS", 9, B_DIM, 150, 34, 78, LV_TEXT_ALIGN_RIGHT);

    b_menu_group(scr, 56, &route, 0);
    b_menu_group(scr, 128, &dev, -1);
    b_menu_group(scr, 200, &sys, -1);

    d_label(scr, "短按 KEY1  下一项", 10, B_MID, 12, 286);
    d_label_w(scr, "长按 KEY1  确认", 10, B_ACCENT, 130, 286, 98,
              LV_TEXT_ALIGN_RIGHT);
    d_label(scr, "短按 KEY2  返回", 10, B_DIM, 12, 302);
}

/* ── 场景入口 ──────────────────────────────────────────────────── */

static void design_b_build(lv_obj_t *scr, int screen)
{
    switch (screen) {
        case DESIGN_SCREEN_RIDE: b_ride(scr); break;
        case DESIGN_SCREEN_MENU: b_menu(scr); break;
        default: b_standby(scr); break;
    }
}

void scene_design_b_create(lv_obj_t *scr, const sim_cfg_t *cfg)
{
    (void)cfg;
    d_scene_start(scr, design_b_build);
