{"content": "/**
 * @file scene_design_c.c
 * @brief WP-DESIGN 方案 C「赛博仪表」：近黑底 + 单一霓虹青、4% 网格、环形/条形
 *        进度承载数据、四角括号 + 角标按键提示。
 *
 * 三个屏幕由 SIM_DESIGN_SCREEN=standby|ride|menu 选择（见 design_common.h）。
 * 纯 LVGL 控件：obj/label/line/arc，无位图、无自定义 draw。
 */

#include "design_common.h"

/* ── 色板（近黑 / 单一霓虹）────────────────────────────────────── */
#define C_BG      0x04070Au   /**< 近黑底 */
#define C_TEXT    0xC8D4DAu   /**< 主文字（灰阶） */
#define C_DIM     0x5C6B74u   /**< 次要文字（灰阶） */
#define C_DIM2    0x2C3941u   /**< 网格加强 / 括号 / 非活动条 */
#define C_NEON    0x7CF7C4u   /**< 唯一霓虹强调色 */
#define C_TRACK   0x16232Au   /**< 环形/条形轨道 */
#define C_SEL     0x081310u   /**< 选中行底 */

/** 4% 白网格，20px 一格。 */
static void c_grid(lv_obj_t *scr)
{
    for (int x = 20; x < 240; x += 20) {
        d_vline(scr, x, 0, 320, 0xFFFFFFu, 10);
    }
    for (int y = 20; y < 320; y += 20) {
        d_hline(scr, 0, y, 240, 0xFFFFFFu, 10);
    }
}

/** 四角括号：corner 坐标 + 向内伸出的两条 10px 线。 */
static void c_brackets(lv_obj_t *scr)
{
    /* 左上 */
    d_hline(scr, 0, 0, 10, C_DIM2, LV_OPA_COVER);
    d_vline(scr, 0, 0, 10, C_DIM2, LV_OPA_COVER);
    /* 右上 */
    d_hline(scr, 230, 0, 10, C_DIM2, LV_OPA_COVER);
    d_vline(scr, 239, 0, 10, C_DIM2, LV_OPA_COVER);
    /* 左下 */
    d_hline(scr, 0, 319, 10, C_DIM2, LV_OPA_COVER);
    d_vline(scr, 0, 310, 10, C_DIM2, LV_OPA_COVER);
    /* 右下 */
    d_hline(scr, 230, 319, 10, C_DIM2, LV_OPA_COVER);
    d_vline(scr, 239, 310, 10, C_DIM2, LV_OPA_COVER);
}

/** 角标按键提示：小 L 括号 + 文字。 */
static void c_key_hint(lv_obj_t *scr, int x, int y, const char *txt, int px,
                       uint32_t color, bool right)
{
    if (right) {
        d_hline(scr, x - 8, y - 3, 8, C_DIM2, LV_OPA_COVER);
        d_vline(scr, x - 1, y - 3, 8, C_DIM2, LV_OPA_COVER);
        d_label_w(scr, txt, px, color, x - 106, y - 4, 98, LV_TEXT_ALIGN_RIGHT);
    } else {
        d_hline(scr, x, y - 3, 8, C_DIM2, LV_OPA_COVER);
        d_vline(scr, x, y - 3, 8, C_DIM2, LV_OPA_COVER);
        d_label(scr, txt, px, color, x + 12, y - 4);
    }
}

/** 环形进度（270° 起始于左下），无旋钮。 */
static lv_obj_t *c_ring(lv_obj_t *scr, int cx, int cy, int d, int pct)
{
    lv_obj_t *arc = lv_arc_create(scr);

    lv_obj_set_size(arc, d, d);
    lv_obj_set_pos(arc, cx - d / 2, cy - d / 2);
    lv_obj_remove_flag(arc, LV_OBJ_FLAG_CLICKABLE);
    lv_obj_remove_flag(arc, LV_OBJ_FLAG_SCROLLABLE);
    lv_obj_set_style_bg_opa(arc, LV_OPA_TRANSP, 0);
    lv_obj_set_style_border_width(arc, 0, 0);
    lv_obj_set_style_outline_width(arc, 0, 0);
    lv_obj_set_style_shadow_width(arc, 0, 0);
    lv_obj_set_style_pad_all(arc, 0, 0);
    lv_obj_set_style_arc_width(arc, 8, LV_PART_MAIN);
    lv_obj_set_style_arc_color(arc, lv_color_hex(C_TRACK), LV_PART_MAIN);
    lv_obj_set_style_arc_rounded(arc, true, LV_PART_MAIN);
    lv_obj_set_style_pad_all(arc, 0, LV_PART_INDICATOR);
    lv_obj_set_style_arc_width(arc, 8, LV_PART_INDICATOR);
    lv_obj_set_style_arc_color(arc, lv_color_hex(C_NEON), LV_PART_INDICATOR);
    lv_obj_set_style_arc_rounded(arc, true, LV_PART_INDICATOR);
    lv_obj_set_style_bg_opa(arc, LV_OPA_TRANSP, LV_PART_KNOB);
    lv_obj_set_style_border_width(arc, 0, LV_PART_KNOB);
    lv_obj_set_style_pad_all(arc, 0, LV_PART_KNOB);
    lv_arc_set_bg_angles(arc, 0, 270);
    lv_arc_set_rotation(arc, 135);
    lv_arc_set_range(arc, 0, 100);
    lv_arc_set_value(arc, pct);
    return arc;
}

static void c_centered(lv_obj_t *scr, const char *txt, int px, uint32_t color,
                       int y)
{
    d_label_w(scr, txt, px, color, 20, y, 200, LV_TEXT_ALIGN_CENTER);
}

/** 横向细条：轨道 + 灰色填充（霓虹只留给环形/当前值）。 */
static void c_bar(lv_obj_t *p, int x, int y, int w, int pct)
{
    d_box(p, x, y, w, 5, C_TRACK, LV_OPA_COVER, 2);
    d_box(p, x, y, w * pct / 100, 5, 0x9FB0B8u, LV_OPA_COVER, 2);
}

/* ── 待机 ──────────────────────────────────────────────────────── */

static void c_standby(lv_obj_t *scr)
{
    d_bg(scr, C_BG);
    c_grid(scr);
    c_brackets(scr);

    d_dot(scr, 14, 16, 4, C_NEON);
    d_label(scr, "GPS 12", 10, C_DIM, 22, 10);
    d_label_w(scr, "定位已锁定", 10, C_DIM, 140, 10, 88, LV_TEXT_ALIGN_RIGHT);

    c_ring(scr, 120, 150, 168, 62);

    c_centered(scr, "本周目标 62%", 10, C_DIM, 100);
    lv_obj_t *trow = d_stack(scr, 40, 112, 160, 58, LV_FLEX_ALIGN_CENTER, 0);
    lv_obj_t *time = lv_label_create(trow);

    lv_label_set_text(time, "08:42");
    lv_obj_set_style_text_font(time, sim_font_cjk(48), 0);
    lv_obj_set_style_text_color(time, lv_color_hex(C_TEXT), 0);
    lv_obj_set_style_text_letter_space(time, 1, 0);

    c_centered(scr, "10月29日 星期四", 10, C_DIM, 176);

    d_label(scr, "上次里程", 10, C_DIM, 14, 242);
    lv_obj_t *lrow = d_stack(scr, 14, 252, 110, 30, LV_FLEX_ALIGN_START, 4);
    lv_obj_t *lv = lv_label_create(lrow);

    lv_label_set_text(lv, "42.6");
    lv_obj_set_style_text_font(lv, sim_font_cjk(22), 0);
    lv_obj_set_style_text_color(lv, lv_color_hex(C_TEXT), 0);
    lv_obj_t *lu = lv_label_create(lrow);

    lv_label_set_text(lu, "km");
    lv_obj_set_style_text_font(lu, sim_font_cjk(10), 0);
    lv_obj_set_style_text_color(lu, lv_color_hex(C_DIM), 0);
    lv_obj_set_style_pad_bottom(lu, 3, 0);

    d_label_w(scr, "用时 1:52:03", 10, C_DIM, 130, 242, 96, LV_TEXT_ALIGN_RIGHT);
    d_label_w(scr, "26.4 km/h", 14, C_TEXT, 130, 256, 96, LV_TEXT_ALIGN_RIGHT);

    c_key_hint(scr, 12, 294, "短按 KEY1 菜单", 10, C_DIM, false);
    c_key_hint(scr, 228, 294, "长按 KEY2 开始", 11, C_NEON, true);
}

/* ── 骑行 ──────────────────────────────────────────────────────── */

static void c_ride(lv_obj_t *scr)
{
    d_bg(scr, C_BG);
    c_grid(scr);
    c_brackets(scr);

    d_dot(scr, 14, 16, 4, C_NEON);
    d_label(scr, "GPS 12", 10, C_DIM, 22, 10);
    d_label_w(scr, "坡度 3.2%", 10, C_DIM, 140, 10, 88, LV_TEXT_ALIGN_RIGHT);

    c_ring(scr, 120, 126, 160, 41);

    c_centered(scr, "时速", 10, C_DIM, 86);
    lv_obj_t *srow = d_stack(scr, 36, 98, 168, 58, LV_FLEX_ALIGN_CENTER, 0);
    lv_obj_t *spd = lv_label_create(srow);

    lv_label_set_text(spd, "24.8");
    lv_obj_set_style_text_font(spd, sim_font_cjk(48), 0);
    lv_obj_set_style_text_color(spd, lv_color_hex(C_TEXT), 0);
    lv_obj_set_style_text_letter_space(spd, 0, 0);
    c_centered(scr, "km/h", 10, C_DIM, 158);

    d_label(scr, "里程", 10, C_DIM, 14, 210);
    d_label(scr, "12.4 km", 14, C_TEXT, 14, 222);
    d_label_w(scr, "时间", 10, C_DIM, 130, 210, 96, LV_TEXT_ALIGN_RIGHT);
    d_label_w(scr, "00:42:18", 14, C_TEXT, 130, 222, 96, LV_TEXT_ALIGN_RIGHT);

    /* 三条灰阶进度：心率 / 踏频 / 海拔 */
    d_label(scr, "心率", 10, C_DIM, 12, 250);
    c_bar(scr, 48, 253, 120, 75);
    d_label_w(scr, "142", 11, C_TEXT, 176, 244, 52, LV_TEXT_ALIGN_RIGHT);

    d_label(scr, "踏频", 10, C_DIM, 12, 266);
    c_bar(scr, 48, 269, 120, 72);
    d_label_w(scr, "86", 11, C_TEXT, 176, 260, 52, LV_TEXT_ALIGN_RIGHT);

    d_label(scr, "海拔", 10, C_DIM, 12, 282);
    c_bar(scr, 48, 285, 120, 33);
    d_label_w(scr, "326 m", 11, C_TEXT, 166, 276, 62, LV_TEXT_ALIGN_RIGHT);

    c_key_hint(scr, 12, 306, "短按 KEY1 切页", 10, C_DIM, false);
    c_key_hint(scr, 228, 306, "长按 KEY2 结束", 11, C_NEON, true);
}

/* ── 菜单 ──────────────────────────────────────────────────────── */

typedef struct {
    const char *group;
    const char *item[2];
    int icon[2];
} c_group_t;

static void c_menu_group(lv_obj_t *scr, int y, const c_group_t *g, int sel,
                         int *index)
{
    d_box(scr, 12, y + 5, 5, 2, C_DIM2, LV_OPA_COVER, 0);
    d_label(scr, g->group, 9, C_DIM, 22, y);

    for (int i = 0; i < 2; i++) {
        const int ry = y + 14 + i * 29;
        const bool on = (sel == i);
        char num[4];

        if (on) {
            d_box(scr, 10, ry, 220, 28, C_SEL, LV_OPA_COVER, 3);
            d_box(scr, 10, ry + 2, 2, 24, C_NEON, LV_OPA_COVER, 1);
        }
        lv_snprintf(num, sizeof(num), "%02d", ++(*index));
        d_label(scr, num, 9, on ? C_NEON : C_DIM2, 18, ry + 7);

        lv_obj_t *box = d_box(scr, 38, ry + 7, 14, 14, 0x000000u, LV_OPA_TRANSP, 2);

        lv_obj_set_style_border_width(box, 1, 0);
        lv_obj_set_style_border_color(box, lv_color_hex(on ? C_NEON : C_DIM2), 0);
        lv_obj_set_style_border_opa(box, LV_OPA_COVER, 0);
        d_box(box, g->icon[i] == 0 ? 5 : 4, g->icon[i] == 0 ? 5 : 4,
              g->icon[i] == 0 ? 4 : 6, g->icon[i] == 0 ? 4 : 4,
              on ? C_NEON : C_DIM2, LV_OPA_COVER, g->icon[i] == 0 ? 2 : 1);

        d_label(scr, g->item[i], 13, on ? C_NEON : C_TEXT, 60, ry + 6);
        d_chevron(scr, 216, ry + 8, on ? C_NEON : C_DIM2, 8);
    }
}

static void c_menu(lv_obj_t *scr)
{
    static const c_group_t route = { "路线", { "路线规划", "历史记录" }, { 0, 1 } };
    static const c_group_t dev = { "设备", { "传感器", "显示" }, { 0, 1 } };
    static const c_group_t sys = { "系统", { "关于", "关机" }, { 0, 1 } };
    int index = 0;

    d_bg(scr, C_BG);
    c_grid(scr);
    c_brackets(scr);

    d_label(scr, "菜单", 20, C_TEXT, 16, 22);
    d_label_w(scr, "MENU / 06", 9, C_DIM, 150, 30, 78, LV_TEXT_ALIGN_RIGHT);
    d_box(scr, 16, 48, 28, 2, C_NEON, LV_OPA_COVER, 1);

    c_menu_group(scr, 56, &route, 0, &index);
    c_menu_group(scr, 128, &dev, -1, &index);
    c_menu_group(scr, 200, &sys, -1, &index);

    d_label(scr, "短按 KEY1 下一项", 10, C_DIM, 12, 284);
    d_label_w(scr, "短按 KEY2 返回", 10, C_DIM, 120, 284, 108,
              LV_TEXT_ALIGN_RIGHT);
    d_label(scr, "长按 KEY1 确认", 10, C_NEON, 12, 302);
}

/* ── 场景入口 ──────────────────────────────────────────────────── */

static void design_c_build(lv_obj_t *scr, int screen)
{
    switch (screen) {
        case DESIGN_SCREEN_RIDE: c_ride(scr); break;
        case DESIGN_SCREEN_MENU: c_menu(scr); break;
        default: c_standby(scr); break;
    }
}

void scene_design_c_create(lv_obj_t *scr, const sim_cfg_t *cfg)
{
    (void)cfg;
    d_scene_start(scr, design_c_build);
}
